    private static int idx() {
        String l = Locale.getDefault().getLanguage();
        for (int i = 0; i < LANGS.length; i++) if (LANGS[i].equals(l)) return i;
        return 0;
    }

    static boolean de() { return idx() == 1; }

    static String t(String key) {
        int c = idx() + 1;
        for (String[] r : T) {
            if (r[0].equals(key)) return (r.length > c && r[c] != null && r[c].length() > 0) ? r[c] : r[1];
        }
        return key;
    }

    static String f(String key, Object... a) { return String.format(t(key), a); }
